import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/controls/OrbitControls.js';
import {buildNature} from './nature-world.js';
const $=id=>document.getElementById(id),canvas=$('nature'),kind=document.body.dataset.landscape,mountain=kind==='mountain';
let renderer;try{renderer=new T.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true})}catch{$('error').hidden=false;throw new Error('WebGL unavailable')}
renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene();scene.background=new T.Color('#f1eee5');scene.fog=new T.Fog('#f1eee5',53,100);
const camera=new T.OrthographicCamera(-15,15,12,-12,.1,140);camera.position.set(23,19,25);
const controls=new OrbitControls(camera,canvas);controls.target.set(0,1.3,0);controls.enableDamping=true;controls.minZoom=.65;controls.maxZoom=4;controls.minPolarAngle=.3;controls.maxPolarAngle=1.45;controls.update();
const sun=new T.DirectionalLight('#fff1d5',2.3);sun.position.set(-11,20,12);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=sun.shadow.camera.bottom=-17;sun.shadow.camera.right=sun.shadow.camera.top=17;sun.shadow.camera.far=65;sun.shadow.normalBias=.025;scene.add(sun);
const hemisphere=new T.HemisphereLight('#f2f5ea','#9caa86',1.6);scene.add(hemisphere);
const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:'#f1eee5',roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-1.58;floor.receiveShadow=true;scene.add(floor);
const env=new T.Scene();env.background=new T.Color('#a9b5ae');const source=new T.Mesh(new T.BoxGeometry(20,.1,20),new T.MeshBasicMaterial({color:'#fffae9'}));source.position.y=14;env.add(source);const pmrem=new T.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(env,.08).texture;pmrem.dispose();
const world=buildNature(kind);scene.add(world.root);
const state={time:0,paused:matchMedia('(prefers-reduced-motion: reduce)').matches,wind:.4,hour:14,detail:false,sound:false,ride:false,gustUntil:0},ray=new T.Raycaster(),mouse=new T.Vector2();
let last=performance.now(),viewMove=null,audio,uiTime=0,touchStart=null;
const tip=text=>$('tip').textContent=text;
function resize(){const rect=canvas.getBoundingClientRect(),aspect=rect.width/rect.height,small=rect.width<650,span=small?Math.max(22,28/aspect):24,shift=small?0:1.5;camera.left=-span*aspect/2+shift;camera.right=span*aspect/2+shift;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio||1,small?1.5:1.8));renderer.setSize(rect.width,rect.height,false);$('gesture').textContent=small?'드래그로 회전 · 두 손가락으로 확대 · 물을 터치해보세요':'드래그로 회전 · 스크롤로 확대 · 물을 눌러 파문 만들기';}new ResizeObserver(resize).observe(canvas.parentElement);resize();
function light(){const p=(state.hour-7)/13,evening=state.hour>16;sun.position.set(-15+30*p,evening?8:20,10);sun.color.set(evening?'#ffbb85':state.hour<10?'#ffe1ac':'#fff1dc');sun.intensity=evening?1.8:2.3;hemisphere.intensity=evening?1.05:1.6;$('timeValue').textContent=String(state.hour).padStart(2,'0')+':00';$('status').textContent=state.ride?(mountain?'숲 위로 올라가는 중':'초원 위를 날아가는 중'):(mountain?'호수 위로 바람이 흐릅니다.':(state.detail?'들꽃 사이로 양들이 걷습니다.':'초원에서 양들이 걷습니다.'));}
function rideOff(){state.ride=false;$('ride').setAttribute('aria-pressed','false');$('ride').querySelector('span').textContent=mountain?'케이블카 타기':'열기구 타기';}
function setView(name){rideOff();const views=mountain?{wide:{p:[23,19,25],t:[0,1.3,0],z:1},detail:{p:[16,11,18],t:[-5,1.7,1.2],z:2.35},water:{p:[16,7,24],t:[1.6,.3,3.5],z:2.2},high:{p:[23,13,20],t:[2,4,-5],z:1.7}}:{wide:{p:[23,19,25],t:[0,1.3,0],z:1},detail:{p:[17,9,19],t:[5,2,-3.5],z:2},water:{p:[17,8,23],t:[1.3,.5,2.6],z:2.1},high:{p:[12,6,19],t:[-4,1,4],z:2.2}};const v=views[name];viewMove={start:performance.now(),from:camera.position.clone(),to:new T.Vector3(...v.p),targetFrom:controls.target.clone(),targetTo:new T.Vector3(...v.t),zoomFrom:camera.zoom,zoom:v.z};document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));light();}
controls.addEventListener('start',()=>{viewMove=null;if(state.ride){rideOff();light();tip('자유롭게 풍경을 둘러보세요.')}});
function chime(){if(!state.sound)return;try{audio||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();for(const [i,f] of [660,880,990].entries()){const osc=audio.createOscillator(),gain=audio.createGain(),at=audio.currentTime+i*.11;osc.type='sine';osc.frequency.value=f;gain.gain.setValueAtTime(.025,at);gain.gain.exponentialRampToValueAtTime(.0001,at+1.1);osc.connect(gain);gain.connect(audio.destination);osc.start(at);osc.stop(at+1.2)}}catch{tip('브라우저에서 소리를 재생할 수 없어요.')}}
function update(ms){requestAnimationFrame(update);const dt=Math.min(.04,(ms-last)/1000);last=ms;const step=state.paused?0:dt;state.time+=step;const gust=state.time<state.gustUntil;world.update(state.time,step,{...state,wind:gust?1:state.wind});
 if(viewMove){const p=Math.min(1,(ms-viewMove.start)/1300),f=p*p*(3-2*p);camera.position.lerpVectors(viewMove.from,viewMove.to,f);controls.target.lerpVectors(viewMove.targetFrom,viewMove.targetTo,f);camera.zoom=T.MathUtils.lerp(viewMove.zoomFrom,viewMove.zoom,f);camera.updateProjectionMatrix();if(p===1)viewMove=null;}
 if(state.ride){const p=world.vehicle.position;controls.target.lerp(p,.045);camera.position.lerp(p.clone().add(new T.Vector3(mountain?6:8,mountain?3:2,mountain?8:10)),.045);camera.zoom=T.MathUtils.lerp(camera.zoom,mountain?2.1:1.5,.035);camera.updateProjectionMatrix();}controls.update();
 uiTime+=dt;if(uiTime>.25){uiTime=0;document.body.classList.toggle('focused-view',state.ride||camera.zoom>1.2);canvas.dataset.frames=String(renderer.info.render.frame);canvas.dataset.vehicle=world.vehicle.position.toArray().map(v=>v.toFixed(2)).join(',');canvas.dataset.time=state.time.toFixed(2);canvas.dataset.mode=state.ride?'ride':'free';canvas.dataset.detail=String(state.detail);}
 renderer.render(scene,camera);
}requestAnimationFrame(update);
canvas.addEventListener('pointerdown',e=>touchStart={x:e.clientX,y:e.clientY});canvas.addEventListener('pointerup',e=>{if(!touchStart||Math.hypot(e.clientX-touchStart.x,e.clientY-touchStart.y)>8){touchStart=null;return}const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);const hit=ray.intersectObject(world.water)[0];if(hit){world.ripple(hit.point.x,hit.point.z,state.time);tip(mountain?'고요한 호수에 작은 파문이 퍼집니다.':'잔잔한 강 위로 작은 파문이 흐릅니다.')}touchStart=null;});canvas.addEventListener('pointercancel',()=>touchStart=null);
$('ride').onclick=()=>{state.ride=!state.ride;viewMove=null;$('ride').setAttribute('aria-pressed',String(state.ride));$('ride').querySelector('span').textContent=state.ride?'풍경으로 돌아가기':mountain?'케이블카 타기':'열기구 타기';if(!state.ride)setView('wide');else{tip(mountain?'케이블카를 따라 숲 위의 시점으로 이동합니다.':'열기구를 따라 초원을 한 바퀴 둘러봅니다.');chime();light();}};
$('gust').onclick=()=>{state.gustUntil=state.time+6;tip(mountain?(state.detail?'숲 사이로 바람이 불고 눈송이가 흩날립니다.':'숲 사이로 바람이 불고 풀잎이 흔들립니다.'):(state.detail?'바람이 들꽃과 풀잎을 흔듭니다.':'바람이 초원의 풀잎을 흔듭니다.'));chime();};
$('detail').onclick=()=>{state.detail=!state.detail;$('detail').setAttribute('aria-pressed',String(state.detail));$('detail').textContent=mountain?(state.detail?'눈 그치기':'눈 내리기'):(state.detail?'들꽃 접기':'들꽃 피우기');tip(mountain?(state.detail?'산에 천천히 눈이 내립니다.':'눈이 그치고 숲이 고요해집니다.'):(state.detail?'초원에 들꽃이 피어납니다.':'들꽃이 접히고 풀밭이 드러납니다.'));};
if(!mountain){state.detail=true;$('detail').setAttribute('aria-pressed','true');$('detail').textContent='들꽃 접기';}
$('wind').oninput=e=>{state.wind=+e.target.value/100;$('windValue').textContent=e.target.value+'%';};$('time').oninput=e=>{state.hour=+e.target.value;document.querySelectorAll('[data-hour]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});light();};
document.querySelectorAll('[data-hour]').forEach(b=>b.onclick=()=>{state.hour=+b.dataset.hour;$('time').value=state.hour;light();document.querySelectorAll('[data-hour]').forEach(v=>{v.classList.toggle('active',v===b);v.setAttribute('aria-pressed',String(v===b))})});
$('pause').onclick=()=>{state.paused=!state.paused;$('pause').textContent=state.paused?'계속 움직이기':'잠시 멈춤';$('pause').setAttribute('aria-pressed',String(state.paused));};if(state.paused){$('pause').textContent='계속 움직이기';$('pause').setAttribute('aria-pressed','true');}
$('sound').onclick=()=>{state.sound=!state.sound;$('sound').textContent=state.sound?'소리 켬':'소리 끔';$('sound').setAttribute('aria-pressed',String(state.sound));chime();};
$('reset').onclick=()=>{state.time=0;state.gustUntil=0;state.wind=.4;state.hour=14;state.detail=!mountain;$('wind').value=40;$('windValue').textContent='40%';$('time').value=14;$('detail').setAttribute('aria-pressed',String(state.detail));$('detail').textContent=mountain?'눈 내리기':'들꽃 접기';document.querySelectorAll('[data-hour]').forEach(b=>{const active=b.dataset.hour==='14';b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});setView('wide');tip('처음 풍경으로 돌아왔어요.');};
$('view').onclick=()=>setView('wide');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
$('trees').textContent=world.features.trees;$('animals').textContent=world.features.creatures;
$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();document.querySelector('.panel-toggle').onclick=e=>{const b=e.currentTarget,open=document.querySelector('.panel').classList.toggle('open');b.setAttribute('aria-expanded',String(open));b.querySelector('span').textContent=open?'접기':'열기';};light();
